<script lang="ts">
 import {onMount} from 'svelte';import RecordTable from '$lib/components/RecordTable.svelte';import {Api} from '$lib/api';
 let devices=$state<any[]>([]);let status=$state<any>({});let filter=$state('');let error=$state('');let shown=$derived(filter?devices.filter(d=>Object.values(d).join(' ').toLowerCase().includes(filter.toLowerCase())):devices);
 async function load(){try{[devices,status]=await Promise.all([Api.bleDevices(),Api.bleStatus()]);error=''}catch(e){error=String(e)}}onMount(load);async function clear(){await Api.bleClear();await load()}
</script>
<div class="page"><h1>Bluetooth LE</h1><p class="muted">Nearby BLE advertisements and discovered devices.</p>{#if error}<p class="error">{error}</p>{/if}<section class="card controls"><b>{devices.length} devices</b><input bind:value={filter} placeholder="Filter devices…"/><button onclick={load}>Refresh</button><button class="danger" onclick={clear}>Clear</button><RecordTable rows={[status]} caption="BLE status" empty="Status is unavailable." /></section><section class="card"><RecordTable rows={shown} caption="BLE devices" empty="No BLE advertisements received. Start a scan or move closer to a device, then refresh." /></section></div>
